public enum Permission {
    READ, WRITE, EXECUTE, ADMIN
}

public class FileManager {
    public void configurePermissions(EnumSet<Permission> permissions) {
        // Bitwise operations under the hood make this blazing fast
        if (permissions.contains(Permission.ADMIN)) {
            grantFullAccess();
        } else {
            grantRestrictedAccess(permissions);
        }
    }

    public static void main(String[] args) {
        // Creating an EnumSet using factory methods
        EnumSet<Permission> activePerms = EnumSet.of(Permission.READ, Permission.WRITE);

        // Complement operation creates an EnumSet of all missing permissions
        EnumSet<Permission> missingPerms = EnumSet.complementOf(activePerms);
    }
}
